using System.Net;
using Microsoft.AspNetCore.HttpOverrides;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddSingleton<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

// Breaking change 1: HttpClientFactory now uses SocketsHttpHandler as the
// default primary handler.  Casting to HttpClientHandler throws
// InvalidCastException.  Use ConfigurePrimaryHttpMessageHandler instead.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new HttpClientHandler { UseCookies = false });

// Breaking change 2: Trace-level HttpClientFactory logs now redact all header
// values by default.  Allowlist the specific non-sensitive headers you need
// to see for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Request-Id"
        && h != "X-Correlation-Id"
        && h != "Content-Type"
        && h != "Accept"));

// Breaking change 3: ForwardedHeadersMiddleware now ignores X-Forwarded-*
// headers from proxies not in KnownProxies or KnownNetworks.  Register your
// trusted reverse-proxy addresses.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // TODO: replace with your actual reverse-proxy address(es)
    options.KnownProxies.Add(IPAddress.Parse("127.0.0.1"));
});

// Breaking change 4: HostBuilder now enables ValidateOnBuild and
// ValidateScopes in development.  The singleton CacheService captures a
// scoped IUserService, which will throw at startup.  Fix: register
// CacheService as scoped so it respects the IUserService scope.
// (The original singleton registration was already incorrect — a singleton
// capturing a scoped service is a "captive dependency" anti-pattern.)

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

// Stub service types (pre-existing in the project)
public interface IUserService { }
public class UserService : IUserService { }
public interface ICacheService { }
public class CacheService(IUserService users) : ICacheService { }

